using UnityEngine;using LWS.TruckTeaParty;
namespace LWS.TruckDentist {
 public sealed class DentalTool:MonoBehaviour {
  public DentistMatch match;public ServingArm arm;public Transform[] models;public SphereCollider[] tips;public Transform rotor;public AudioSource workAudio;public AudioClip rotaryClip,airClip;public LineRenderer jet;public DentalToolKind Kind{get;private set;}public bool Running;public int NativeContacts{get;private set;}public DentalTooth Gripped{get;private set;}public Vector3 Tip=>tips[(int)Kind].transform.TransformPoint(tips[(int)Kind].center);
  // Tip is the original rendered/interpolated presentation/contact readout.
  // AI positioning must not subtract it from a physics Rigidbody.position:
  // undo the rendered hierarchy, then apply the real current physics pose.
  public Vector3 PhysicalTipOffset=>arm.grip.rotation*Vector3.Scale(arm.grip.transform.InverseTransformPoint(Tip),arm.grip.transform.lossyScale);
  public Vector3 PhysicalTip=>arm.grip.position+PhysicalTipOffset;
  public float TipSpeed{get;private set;}Vector3 previousTip;ConfigurableJoint gripJoint;
  public void Prepare(){Release();NativeContacts=0;if(workAudio!=null)workAudio.Stop();Kind=(DentalToolKind)(-1);Running=false;Select(DentalToolKind.Brush);previousTip=Tip;}
  public void Select(DentalToolKind kind){if(kind==Kind)return;Release();Kind=kind;for(int i=0;i<models.Length;i++)models[i].gameObject.SetActive(i==(int)kind);arm.RefreshOwnCollisionIsolation();previousTip=Tip;}
  public void Release(){if(gripJoint!=null){gripJoint.xMotion=gripJoint.yMotion=gripJoint.zMotion=ConfigurableJointMotion.Free;gripJoint.angularXMotion=gripJoint.angularYMotion=gripJoint.angularZMotion=ConfigurableJointMotion.Free;Destroy(gripJoint);}gripJoint=null;Gripped=null;}
  public void Tick(float dt){if(workAudio!=null){if(!Running||!match.Live)workAudio.Stop();else{var desired=Kind==DentalToolKind.Drill||Kind==DentalToolKind.Brush||Kind==DentalToolKind.Cleaner?rotaryClip:airClip;if(workAudio.clip!=desired){workAudio.Stop();workAudio.clip=desired;}if(!workAudio.isPlaying&&workAudio.clip!=null)workAudio.Play();}}TipSpeed=dt>0?Vector3.Distance(Tip,previousTip)/dt:0;previousTip=Tip;if(!Running){Release();jet.enabled=false;return;}if(Kind==DentalToolKind.Drill||Kind==DentalToolKind.Brush||Kind==DentalToolKind.Cleaner)models[(int)Kind].Rotate(Vector3.forward,dt*(Kind==DentalToolKind.Drill?900:180),Space.Self);jet.enabled=Kind==DentalToolKind.Water||Kind==DentalToolKind.Air;if(jet.enabled){jet.positionCount=2;jet.SetPosition(0,Tip);jet.SetPosition(1,Tip+arm.truck.transform.forward*.4f);}}
  public void NativeContact(DentalTooth tooth,Collision collision){if(!match.Live||!match.rules.Active||!Running||tooth.match!=match||collision.collider!=tips[(int)Kind])return;NativeContacts++;tooth.LastContactTool=this;float force=collision.impulse.magnitude/Mathf.Max(.001f,Time.fixedDeltaTime);float speed=collision.relativeVelocity.magnitude;match.NativeWork(tooth,this,Mathf.Max(speed,TipSpeed),force);TryClamp(tooth);}
  void TryClamp(DentalTooth tooth){if(Kind==DentalToolKind.Extractor&&Gripped==null&&TipSpeed<1.5f&&!tooth.Broken&&!tooth.Extracted){Gripped=tooth;tooth.LastExtractor=this;gripJoint=tooth.gameObject.AddComponent<ConfigurableJoint>();gripJoint.connectedBody=arm.grip;gripJoint.autoConfigureConnectedAnchor=false;gripJoint.anchor=tooth.transform.InverseTransformPoint(Tip);gripJoint.connectedAnchor=arm.grip.transform.InverseTransformPoint(Tip);gripJoint.xMotion=gripJoint.yMotion=gripJoint.zMotion=ConfigurableJointMotion.Locked;gripJoint.angularXMotion=gripJoint.angularYMotion=gripJoint.angularZMotion=ConfigurableJointMotion.Locked;gripJoint.enableCollision=false;}}
  void OnTriggerStay(Collider other){if(!Running||!match.Live||!match.rules.Active||Kind!=DentalToolKind.Water&&Kind!=DentalToolKind.Air&&Kind!=DentalToolKind.Extractor)return;var tooth=other.attachedRigidbody!=null?other.attachedRigidbody.GetComponent<DentalTooth>():null;if(tooth==null||tooth.match!=match||(other.ClosestPoint(Tip)-Tip).sqrMagnitude>tips[(int)Kind].radius*tips[(int)Kind].radius+.0001f)return;NativeContacts++;tooth.LastContactTool=this;match.NativeWork(tooth,this,TipSpeed,0);TryClamp(tooth);}

 }
}
